bool t1 = false;
try { Solution.Transfer(100m, 50m, 0m); } catch (ArgumentException) { t1 = true; }
bool t2 = false;
try { Solution.Transfer(10m, 50m, 20m); } catch (InvalidOperationException) { t2 = true; }
Cj.True(t1 && t2, "both contracts enforced");

var log = new List<string>();
bool ok = Solution.AuditTrail(log, () => log.Add("work"));
Cj.True(ok, "success returns true");
Cj.Eq(string.Join(",", log), "work,done", "done appended after success");
var log2 = new List<string>();
bool threw = false;
try { Solution.AuditTrail(log2, () => throw new InvalidOperationException()); } catch (InvalidOperationException) { threw = true; }
Cj.True(threw, "exception propagates");
Cj.Eq(log2.Count, 1, "done still appended on failure");
Cj.Eq(log2[0], "done", "and it is exactly done");
